def run_query(rows: list[dict], query: dict) -> list[dict]:
    OP_AND = 0
    OP_OR = 1
    OP_NOT = 2
    OP_CMP = 3
    OP_ISNULL = 4
    OP_IN = 5
    OP_BETWEEN = 6

    K_COL = 0
    K_VAL = 1
    K_AGG = 2

    CMP_EQ = 0
    CMP_NE = 1
    CMP_LT = 2
    CMP_LE = 3
    CMP_GT = 4
    CMP_GE = 5
    CMP_CODES = {
        "=": CMP_EQ,
        "!=": CMP_NE,
        "<": CMP_LT,
        "<=": CMP_LE,
        ">": CMP_GT,
        ">=": CMP_GE,
    }

    K_ROW = 0
    K_COUNT = 1
    K_CDIS = 2
    K_SUM = 3
    K_AVG = 4
    K_MIN = 5
    K_MAX = 6

    select_items = query["select"]
    where_cond = query.get("where")
    group_by = query.get("group_by") or []
    group_by = list(group_by)
    having_cond = query.get("having")
    distinct = query.get("distinct", False)
    order_by = query.get("order_by") or []
    offset = query.get("offset")
    limit = query.get("limit")

    has_select_aggs = any(isinstance(item, list) for item in select_items)
    do_group = bool(group_by) or has_select_aggs

    agg_specs = []
    agg_index = {}

    def add_spec(func, arg):
        spec = (func, arg)
        if spec not in agg_index:
            agg_index[spec] = len(agg_specs)
            agg_specs.append(spec)

    for item in select_items:
        if isinstance(item, list):
            add_spec(item[0], item[1])

    if having_cond is not None:
        def collect_operand(opd):
            if opd[0] == "agg":
                add_spec(opd[1], opd[2])

        def collect_aggs(c):
            op = c[0]
            if op == "and" or op == "or":
                collect_aggs(c[1])
                collect_aggs(c[2])
            elif op == "not":
                collect_aggs(c[1])
            elif op == "is_null":
                collect_operand(c[1])
            elif op == "in":
                collect_operand(c[1])
            elif op == "between":
                collect_operand(c[1])
            elif op in CMP_CODES:
                collect_operand(c[1])
                collect_operand(c[2])

        collect_aggs(having_cond)

    def compile_operand(opd):
        t = opd[0]
        if t == "col":
            return (K_COL, opd[1], -1)
        if t == "val":
            return (K_VAL, opd[1], -1)
        return (K_AGG, opd[1], opd[2])

    def compile_cond(c):
        op = c[0]
        if op == "and":
            return (OP_AND, compile_cond(c[1]), compile_cond(c[2]))
        if op == "or":
            return (OP_OR, compile_cond(c[1]), compile_cond(c[2]))
        if op == "not":
            return (OP_NOT, compile_cond(c[1]))
        if op in CMP_CODES:
            return (OP_CMP, CMP_CODES[op], compile_operand(c[1]), compile_operand(c[2]))
        if op == "is_null":
            return (OP_ISNULL, compile_operand(c[1]))
        if op == "in":
            return (OP_IN, compile_operand(c[1]), c[2])
        if op == "between":
            return (OP_BETWEEN, compile_operand(c[1]), c[2], c[3])
        raise ValueError("invalid condition")

    where_node = compile_cond(where_cond) if where_cond is not None else None
    having_node = compile_cond(having_cond) if having_cond is not None else None

    select_plan = []
    for item in select_items:
        if isinstance(item, str):
            select_plan.append(("col", item, item))
        else:
            func, arg = item
            select_plan.append(("agg", f"{func}({arg})", agg_index[(func, arg)]))

    slots_init = []
    set_slot_indices = []
    spec_accum = []
    update_ops = []
    row_count_slot = None

    for func, arg in agg_specs:
        if func == "count":
            if arg == "*":
                if row_count_slot is None:
                    row_count_slot = len(slots_init)
                    slots_init.append(0)
                spec_accum.append((K_ROW, row_count_slot, -1))
            else:
                idx = len(slots_init)
                slots_init.append(0)
                spec_accum.append((K_COUNT, idx, -1))
                update_ops.append((arg, K_COUNT, idx, -1))
        elif func == "count_distinct":
            idx = len(slots_init)
            slots_init.append(None)
            set_slot_indices.append(idx)
            spec_accum.append((K_CDIS, idx, -1))
            update_ops.append((arg, K_CDIS, idx, -1))
        elif func == "sum":
            s_idx = len(slots_init)
            slots_init.append(0)
            c_idx = len(slots_init)
            slots_init.append(0)
            spec_accum.append((K_SUM, s_idx, c_idx))
            update_ops.append((arg, K_SUM, s_idx, c_idx))
        elif func == "avg":
            s_idx = len(slots_init)
            slots_init.append(0)
            c_idx = len(slots_init)
            slots_init.append(0)
            spec_accum.append((K_AVG, s_idx, c_idx))
            update_ops.append((arg, K_SUM, s_idx, c_idx))
        elif func == "min":
            idx = len(slots_init)
            slots_init.append(None)
            spec_accum.append((K_MIN, idx, -1))
            update_ops.append((arg, K_MIN, idx, -1))
        elif func == "max":
            idx = len(slots_init)
            slots_init.append(None)
            spec_accum.append((K_MAX, idx, -1))
            update_ops.append((arg, K_MAX, idx, -1))

    if set_slot_indices:
        base_init = slots_init
        set_idx = tuple(set_slot_indices)

        def make_state():
            st = base_init.copy()
            for i in set_idx:
                st[i] = set()
            return st
    else:
        base_init = slots_init.copy()

        def make_state():
            return base_init.copy()

    def agg_value(spec_i, state):
        kind, i0, i1 = spec_accum[spec_i]
        if kind == K_ROW or kind == K_COUNT:
            return state[i0]
        if kind == K_CDIS:
            return len(state[i0])
        if kind == K_SUM:
            cnt = state[i1]
            return None if cnt == 0 else state[i0]
        if kind == K_AVG:
            cnt = state[i1]
            return None if cnt == 0 else state[i0] // cnt
        if kind == K_MIN:
            return state[i0]
        return state[i0]

    def update_state(state, row):
        if row_count_slot is not None:
            state[row_count_slot] += 1
        for arg, kind, i0, i1 in update_ops:
            v = row[arg]
            if v is None:
                continue
            if kind == K_COUNT:
                state[i0] += 1
            elif kind == K_CDIS:
                state[i0].add(v)
            elif kind == K_SUM:
                state[i0] += v
                state[i1] += 1
            elif kind == K_MIN:
                cur = state[i0]
                if cur is None or v < cur:
                    state[i0] = v
            else:
                cur = state[i0]
                if cur is None or v > cur:
                    state[i0] = v

    def eval_where(node, row):
        op = node[0]

        if op == OP_AND:
            a = eval_where(node[1], row)
            if a is False:
                return False
            b = eval_where(node[2], row)
            if b is False:
                return False
            if a is None or b is None:
                return None
            return True

        if op == OP_OR:
            a = eval_where(node[1], row)
            if a is True:
                return True
            b = eval_where(node[2], row)
            if b is True:
                return True
            if a is None or b is None:
                return None
            return False

        if op == OP_NOT:
            a = eval_where(node[1], row)
            if a is None:
                return None
            return not a

        if op == OP_ISNULL:
            opd = node[1]
            v = row[opd[1]] if opd[0] == K_COL else opd[1]
            return v is None

        if op == OP_IN:
            opd = node[1]
            x = row[opd[1]] if opd[0] == K_COL else opd[1]
            lst = node[2]
            if not lst:
                return False
            if x is None:
                return None
            contains_null = False
            for v in lst:
                if v is None:
                    contains_null = True
                elif x == v:
                    return True
            return None if contains_null else False

        if op == OP_BETWEEN:
            opd = node[1]
            x = row[opd[1]] if opd[0] == K_COL else opd[1]
            lo = node[2]
            hi = node[3]
            if x is None:
                return None
            r1 = None if lo is None else (x >= lo)
            r2 = None if hi is None else (x <= hi)
            if r1 is False or r2 is False:
                return False
            if r1 is None or r2 is None:
                return None
            return True

        c = node[1]
        ox = node[2]
        oy = node[3]
        x = row[ox[1]] if ox[0] == K_COL else ox[1]
        y = row[oy[1]] if oy[0] == K_COL else oy[1]
        if x is None or y is None:
            return None

        if c == CMP_EQ:
            return x == y
        if c == CMP_NE:
            return x != y
        if c == CMP_LT:
            return x < y
        if c == CMP_LE:
            return x <= y
        if c == CMP_GT:
            return x > y
        return x >= y

    group_by_index = {name: i for i, name in enumerate(group_by)}

    def get_having_operand(opd, state, key):
        t = opd[0]
        if t == K_COL:
            idx = group_by_index.get(opd[1])
            return key[idx] if idx is not None else None
        if t == K_VAL:
            return opd[1]
        return agg_value(agg_index[(opd[1], opd[2])], state)

    def eval_having(node, state, key):
        op = node[0]

        if op == OP_AND:
            a = eval_having(node[1], state, key)
            if a is False:
                return False
            b = eval_having(node[2], state, key)
            if b is False:
                return False
            if a is None or b is None:
                return None
            return True

        if op == OP_OR:
            a = eval_having(node[1], state, key)
            if a is True:
                return True
            b = eval_having(node[2], state, key)
            if b is True:
                return True
            if a is None or b is None:
                return None
            return False

        if op == OP_NOT:
            a = eval_having(node[1], state, key)
            if a is None:
                return None
            return not a

        if op == OP_ISNULL:
            return get_having_operand(node[1], state, key) is None

        if op == OP_IN:
            x = get_having_operand(node[1], state, key)
            lst = node[2]
            if not lst:
                return False
            if x is None:
                return None
            contains_null = False
            for v in lst:
                if v is None:
                    contains_null = True
                elif x == v:
                    return True
            return None if contains_null else False

        if op == OP_BETWEEN:
            x = get_having_operand(node[1], state, key)
            lo = node[2]
            hi = node[3]
            if x is None:
                return None
            r1 = None if lo is None else (x >= lo)
            r2 = None if hi is None else (x <= hi)
            if r1 is False or r2 is False:
                return False
            if r1 is None or r2 is None:
                return None
            return True

        c = node[1]
        ox = node[2]
        oy = node[3]
        x = get_having_operand(ox, state, key)
        y = get_having_operand(oy, state, key)
        if x is None or y is None:
            return None

        if c == CMP_EQ:
            return x == y
        if c == CMP_NE:
            return x != y
        if c == CMP_LT:
            return x < y
        if c == CMP_LE:
            return x <= y
        if c == CMP_GT:
            return x > y
        return x >= y

    def make_plain_row(row):
        d = {}
        for kind, out_key, ref in select_plan:
            if kind == "col":
                d[out_key] = row[ref]
        return d

    def make_group_row(group_key, state):
        d = {}
        for kind, out_key, ref in select_plan:
            if kind == "col":
                idx = group_by_index.get(ref)
                d[out_key] = group_key[idx] if idx is not None else None
            else:
                d[out_key] = agg_value(ref, state)
        return d

    out = []

    if do_group:
        groups = {}
        if not group_by:
            key = ()
            groups[key] = make_state() if agg_specs else None

        for row in rows:
            if where_node is not None and eval_where(where_node, row) is not True:
                continue

            if group_by:
                key = tuple(row[c] for c in group_by)
            else:
                key = ()

            if agg_specs:
                state = groups.get(key)
                if state is None:
                    state = make_state()
                    groups[key] = state
                update_state(state, row)
            else:
                if key not in groups:
                    groups[key] = None

        if having_node is not None:
            for group_key, state in groups.items():
                if eval_having(having_node, state, group_key) is True:
                    out.append(make_group_row(group_key, state))
        else:
            for group_key, state in groups.items():
                out.append(make_group_row(group_key, state))
    else:
        if where_node is not None:
            for row in rows:
                if eval_where(where_node, row) is True:
                    out.append(make_plain_row(row))
        else:
            for row in rows:
                out.append(make_plain_row(row))

    if distinct:
        seen = set()
        deduped = []
        for d in out:
            k = tuple(d.values())
            if k not in seen:
                seen.add(k)
                deduped.append(d)
        out = deduped

    if order_by:
        for item in reversed(order_by):
            key_name, direction, nulls = item
            k = key_name

            if direction == "desc":
                reverse = True
                if nulls == "first":
                    null_rank = 1
                    nonnull_rank = 0
                else:
                    null_rank = 0
                    nonnull_rank = 1
            else:
                reverse = False
                if nulls == "last":
                    null_rank = 1
                    nonnull_rank = 0
                else:
                    null_rank = 0
                    nonnull_rank = 1

            def sort_key(r):
                v = r[k]
                if v is None:
                    return (null_rank, None)
                return (nonnull_rank, v)

            out.sort(key=sort_key, reverse=reverse)

    if offset is not None or limit is not None:
        start = offset if offset is not None else 0
        if limit is not None:
            out = out[start:start + limit]
        else:
            out = out[start:]

    return out
```
